#include "../src/enemy_behavior_rules.h"
#include <cassert>
int main() { assert(PatrolPhaseDirection(0, 2) == 1); assert(PatrolPhaseDirection(2, 2) == -1); assert(PatrolPhaseDirection(4, 2) == 1); assert(PatrolPhaseDirection(0, 2, -1) == -1); assert(PatrolPhaseDirection(2, 2, -1) == 1); assert(!VerticalPatrolLimitReached(100, 4, 404)); assert(VerticalPatrolLimitReached(101, 4, 404)); assert(JumpInitialSpeed(8) < 0); assert(EnemyDeathHasPriority(true)); assert(!EnemyDeathHasPriority(false)); int anchor_x=0, anchor_y=0, dir_x=1, dir_y=1; StepPatrolAxis(4, 4, anchor_x, dir_x); StepPatrolAxis(5, 4, anchor_x, dir_x); assert(anchor_x==5 && dir_x==-1); StepPatrolAxis(3, 4, anchor_y, dir_y); assert(anchor_y==0 && dir_y==1); StepPatrolAxis(5, 4, anchor_y, dir_y); assert(anchor_y==5 && dir_y==-1); return 0; }
